using System;
using System.Collections.Generic;
using System.Linq;
using Betta.Attributes;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>
    /// One four-sided facade panel cut from a surface. Passed between components
    /// as a single opaque "Panel" value.
    /// </summary>
    [GrasshopperOpaque]
    public sealed class Panel
    {
        private readonly Point3d[] _corners;

        public Panel(Point3d c0, Point3d c1, Point3d c2, Point3d c3, int index, int u = -1, int v = -1)
        {
            _corners = new[] { c0, c1, c2, c3 };
            Index = index;
            U = u;
            V = v;
            Area = ComputeArea(_corners);
            Deviation = ComputeDeviation(_corners);
        }

        /// <summary>Index of the panel in the grid (row-major: V * U Count + U).</summary>
        public int Index { get; }

        /// <summary>Column of the grid cell (-1 if unknown).</summary>
        public int U { get; }

        /// <summary>Row of the grid cell (-1 if unknown).</summary>
        public int V { get; }

        /// <summary>The four corners, in order around the panel.</summary>
        public IReadOnlyList<Point3d> Corners => _corners;

        /// <summary>Area of the panel (sum of the two triangles split along the 0-2 diagonal).</summary>
        public double Area { get; }

        /// <summary>Distance from the fourth corner to the plane through the first three.</summary>
        public double Deviation { get; }

        public Point3d Center => new Point3d(
            _corners.Average(p => p.X),
            _corners.Average(p => p.Y),
            _corners.Average(p => p.Z));

        /// <summary>A new closed polyline curve through the four corners.</summary>
        public Curve Outline => new PolylineCurve(new[] { _corners[0], _corners[1], _corners[2], _corners[3], _corners[0] });

        /// <summary>Edge lengths: 0-1, 1-2, 2-3, 3-0.</summary>
        public double[] EdgeLengths => new[]
        {
            _corners[0].DistanceTo(_corners[1]),
            _corners[1].DistanceTo(_corners[2]),
            _corners[2].DistanceTo(_corners[3]),
            _corners[3].DistanceTo(_corners[0]),
        };

        /// <summary>Diagonal lengths: 0-2, 1-3.</summary>
        public double[] DiagonalLengths => new[]
        {
            _corners[0].DistanceTo(_corners[2]),
            _corners[1].DistanceTo(_corners[3]),
        };

        /// <summary>Rectangle width for nesting: mean of the first and third edges.</summary>
        public double NestWidth
        {
            get { var e = EdgeLengths; return (e[0] + e[2]) / 2.0; }
        }

        /// <summary>Rectangle height for nesting: mean of the second and fourth edges.</summary>
        public double NestHeight
        {
            get { var e = EdgeLengths; return (e[1] + e[3]) / 2.0; }
        }

        public override string ToString()
            => U >= 0 && V >= 0
                ? $"Panel {Index} ({U},{V}) A={Area:0.###} dev={Deviation:0.###}"
                : $"Panel {Index} A={Area:0.###} dev={Deviation:0.###}";

        private static double ComputeArea(Point3d[] c)
        {
            var a = Vector3d.CrossProduct(c[1] - c[0], c[2] - c[0]).Length;
            var b = Vector3d.CrossProduct(c[2] - c[0], c[3] - c[0]).Length;
            return 0.5 * (a + b);
        }

        private static double ComputeDeviation(Point3d[] c)
        {
            var plane = new Plane(c[0], c[1], c[2]);
            if (!plane.IsValid) return 0.0; // first three corners collinear: no defined plane
            return Math.Abs(plane.DistanceTo(c[3]));
        }
    }
}

