using System;
using System.Collections.Generic;
using System.Linq;
using Betta.Attributes;
using Betta.Interfaces;

namespace BenchPlugin.Facade
{
    [GrasshopperCollection("Facade", "Analysis")]
    public interface IPanelAnalysis : IBettaCollection
    {
        [GrasshopperMethod("Planarity", "Planarity deviation of each panel and whether it is flat within tolerance")]
        (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            [GrasshopperParameter("Panels", "P", "Panels to check")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", "T", "Maximum deviation for a flat panel", DefaultValue = 0.5)] double tolerance,
            IBettaReport report);

        [GrasshopperMethod("Classify Panels", "Classifies panels as flat, cold-bent or custom by planarity deviation")]
        (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            [GrasshopperParameter("Panels", "P", "Panels to classify")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", "T", "Flat tolerance; cold-bent up to 10x this", DefaultValue = 0.5)] double tolerance);

        [GrasshopperMethod("Panel Stats", "Total, minimum, maximum and mean panel area")]
        (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(
            [GrasshopperParameter("Panels", "P", "Panels to measure")] List<Panel> panels);
    }

    public class PanelAnalysis : IPanelAnalysis
    {
        public const string Flat = "flat";
        public const string ColdBent = "cold-bent";
        public const string Custom = "custom";

        public (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            List<Panel> panels, double tolerance, IBettaReport report)
        {
            PanelChecks.RequireNoNulls(panels);
            PanelChecks.RequireNonNegative(tolerance, "Tolerance");

            var deviation = panels.Select(p => p.Deviation).ToList();
            var flat = deviation.Select(d => d <= tolerance).ToList();
            int flatCount = flat.Count(f => f);
            int notFlat = panels.Count - flatCount;

            if (notFlat * 2 > panels.Count)
                report?.Warning($"{notFlat} of {panels.Count} panels are not flat (deviation above {tolerance})");

            return (deviation, flat, flatCount);
        }

        public (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            List<Panel> panels, double tolerance)
        {
            PanelChecks.RequireNoNulls(panels);
            PanelChecks.RequireNonNegative(tolerance, "Tolerance");

            var types = new List<string>(panels.Count);
            int flat = 0, cold = 0, custom = 0;
            foreach (var p in panels)
            {
                if (p.Deviation <= tolerance) { types.Add(Flat); flat++; }
                else if (p.Deviation <= 10.0 * tolerance) { types.Add(ColdBent); cold++; }
                else { types.Add(Custom); custom++; }
            }
            return (types, flat, cold, custom);
        }

        public (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(List<Panel> panels)
        {
            PanelChecks.RequireNoNulls(panels);
            if (panels.Count == 0) throw new ArgumentException("No panels");

            var areas = panels.Select(p => p.Area).ToList();
            return (areas.Sum(), areas.Min(), areas.Max(), areas.Average());
        }
    }

    internal static class PanelChecks
    {
        public static void RequireNoNulls(List<Panel> panels)
        {
