using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Betta.Attributes;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    [GrasshopperCollection("Facade", "Fabrication")]
    public interface IFabrication : IBettaCollection
    {
        [GrasshopperMethod("Group Identical Panels", "Groups panels whose sorted edge and diagonal lengths match within tolerance")]
        (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            [GrasshopperParameter("Panels", "P", "Panels to group")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", "T", "Maximum length difference", DefaultValue = 1.0)] double tolerance);

        [GrasshopperMethod("Nest On Sheets", "Shelf-nests panel rectangles onto sheets")]
        Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            [GrasshopperParameter("Panels", "P", "Panels to nest")] List<Panel> panels,
            [GrasshopperParameter("Sheet Width", "W", "Sheet width", DefaultValue = 3000.0)] double sheetWidth,
            [GrasshopperParameter("Sheet Height", "H", "Sheet height", DefaultValue = 1500.0)] double sheetHeight,
            [GrasshopperParameter("Spacing", "S", "Gap between parts and from the sheet edge", DefaultValue = 10.0)] double spacing,
            CancellationToken cancellationToken,
            IProgress<string> progress,
            IBettaReport report);

        [GrasshopperMethod("Cut List", "CSV cut list of panels, optionally written to a file")]
        (string CSV, bool Written) CutList(
            [GrasshopperParameter("Panels", "P", "Panels to list")] List<Panel> panels,
            [GrasshopperParameter("Path", "F", "File path for the CSV", DefaultValue = "")] string path,
            [GrasshopperParameter("Write", "Wr", "Write the CSV to Path", DefaultValue = false)] bool write);
    }

    public class Fabrication : IFabrication
    {
        /// <summary>Gap along X between consecutive sheets in the output layout.</summary>
        public const double SheetGap = 100.0;

        public (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            List<Panel> panels, double tolerance)
        {
            PanelChecks.RequireNoNulls(panels);
            PanelChecks.RequireNonNegative(tolerance, "Tolerance");

            var reps = new List<Panel>();
            var repKeys = new List<double[]>();
            var groups = new List<int>(panels.Count);

            foreach (var p in panels)
            {
                var key = ShapeKey(p);
                int found = -1;
                for (int g = 0; g < repKeys.Count; g++)
                {
                    if (Matches(repKeys[g], key, tolerance)) { found = g; break; }
                }
                if (found < 0)
                {
                    found = reps.Count;
                    reps.Add(p);
                    repKeys.Add(key);
                }
                groups.Add(found);
            }
            return (groups, reps.Count, reps);
        }

        // Sorted edges (4) followed by sorted diagonals (2).
        private static double[] ShapeKey(Panel p)
        {
            var edges = p.EdgeLengths.OrderBy(x => x);
            var diags = p.DiagonalLengths.OrderBy(x => x);
            return edges.Concat(diags).ToArray();
        }

        private static bool Matches(double[] a, double[] b, double tolerance)
        {
            for (int i = 0; i < a.Length; i++)
                if (Math.Abs(a[i] - b[i]) > tolerance) return false;
            return true;
        }

        public Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            List<Panel> panels, double sheetWidth, double sheetHeight, double spacing,
            CancellationToken cancellationToken, IProgress<string> progress, IBettaReport report)
        {
            PanelChecks.RequireNoNulls(panels);
            if (!(sheetWidth > 0)) throw new ArgumentOutOfRangeException(nameof(sheetWidth), "Sheet Width must be positive");
            if (!(sheetHeight > 0)) throw new ArgumentOutOfRangeException(nameof(sheetHeight), "Sheet Height must be positive");
            PanelChecks.RequireNonNegative(spacing, "Spacing");

            // Snapshot the sizes on the calling thread; the packing runs off the UI thread.
            var parts = panels.Select(p => (Width: p.NestWidth, Height: p.NestHeight)).ToList();

            return Task.Run(() => ShelfPack(parts, sheetWidth, sheetHeight, spacing, cancellationToken, progress, report),
                cancellationToken);
        }

        private static (List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization) ShelfPack(
            List<(double Width, double Height)> parts, double sheetW, double sheetH, double spacing,
            CancellationToken ct, IProgress<string> progress, IBettaReport report)
        {
            double maxX = sheetW - spacing; // right usable edge
            double maxY = sheetH - spacing; // top usable edge

            // Tallest first (stable for equal heights).
            var order = Enumerable.Range(0, parts.Count)
                .OrderByDescending(i => parts[i].Height)
                .ToList();

            var outlines = new List<Curve>();
            var sheetOf = new List<int>();
            double placedArea = 0;
            int unplaced = 0;

            int sheet = -1;          // current sheet index (-1: none opened yet)
            double shelfY = 0;       // bottom of the current shelf
            double shelfH = 0;       // height of the current shelf
            double cursorX = 0;      // next free x on the current shelf

            bool FitsAt(double x, double y, double w, double h) => x + w <= maxX + 1e-9 && y + h <= maxY + 1e-9;

            void OpenSheet()
            {
                sheet++;
                shelfY = spacing;
                shelfH = 0;
                cursorX = spacing;
            }

            void OpenShelf()
            {
                shelfY = shelfY + shelfH + spacing;
                shelfH = 0;
                cursorX = spacing;
            }

            // Try the part as-is, then turned 90 degrees, at the current cursor.
            bool TryPlace(double w, double h, out double pw, out double ph)
            {
                if (FitsAt(cursorX, shelfY, w, h)) { pw = w; ph = h; return true; }
                if (FitsAt(cursorX, shelfY, h, w)) { pw = h; ph = w; return true; }
                pw = ph = 0;
                return false;
            }

            int lastPercent = -1;
            for (int n = 0; n < order.Count; n++)
            {
                ct.ThrowIfCancellationRequested();

                var (w, h) = parts[order[n]];

                // A part that fits on no empty sheet in either orientation is skipped.
                bool fitsEmpty = FitsAt(spacing, spacing, w, h) || FitsAt(spacing, spacing, h, w);
                if (!fitsEmpty || w <= 0 || h <= 0)
                {
                    unplaced++;
                    continue;
                }

                if (sheet < 0) OpenSheet();

                double pw, ph;
                if (!TryPlace(w, h, out pw, out ph))
                {
                    OpenShelf();
                    if (!TryPlace(w, h, out pw, out ph))
                    {
                        OpenSheet();
                        TryPlace(w, h, out pw, out ph); // guaranteed by fitsEmpty
                    }
                }

                double offsetX = sheet * (sheetW + SheetGap);
                var x0 = offsetX + cursorX;
                var y0 = shelfY;
                outlines.Add(new PolylineCurve(new[]
                {
                    new Point3d(x0, y0, 0),
                    new Point3d(x0 + pw, y0, 0),
                    new Point3d(x0 + pw, y0 + ph, 0),
                    new Point3d(x0, y0 + ph, 0),
                    new Point3d(x0, y0, 0),
                }));
                sheetOf.Add(sheet);
                placedArea += pw * ph;

                cursorX += pw + spacing;
                if (ph > shelfH) shelfH = ph;

                int percent = (int)(100.0 * (n + 1) / order.Count);
                if (percent != lastPercent)
                {
                    lastPercent = percent;
                    progress?.Report($"Nesting {percent}%");
                }
            }

            int sheetCount = sheet + 1;
            double utilization = sheetCount > 0 ? placedArea / (sheetCount * sheetW * sheetH) : 0.0;

            if (unplaced > 0)
                report?.Warning($"{unplaced} of {parts.Count} panels fit on no sheet and were not nested");

            return (outlines, sheetOf, sheetCount, utilization);
        }

        public (string CSV, bool Written) CutList(List<Panel> panels, string path, bool write)
        {
            PanelChecks.RequireNoNulls(panels);

            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder();
            sb.Append("Index,Width,Height,Area,Deviation\n");
            foreach (var p in panels)
            {
                sb.Append(p.Index.ToString(inv)).Append(',')
                  .Append(p.NestWidth.ToString("0.###", inv)).Append(',')
                  .Append(p.NestHeight.ToString("0.###", inv)).Append(',')
                  .Append(p.Area.ToString("0.###", inv)).Append(',')
                  .Append(p.Deviation.ToString("0.####", inv)).Append('\n');
            }
            var csv = sb.ToString();

            if (!write) return (csv, false);
            if (string.IsNullOrWhiteSpace(path)) throw new ArgumentException("Write is true but Path is empty");

            var dir = Path.GetDirectoryName(Path.GetFullPath(path));
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
            File.WriteAllText(path, csv);
            return (csv, true);
        }
    }
}

